mapper.select:
SELECT merchant_id, balance, total_income, currency, version, created_at, updated_at
FROM merchant_account
WHERE merchant_id = #{merchantId}

mapper.update:
UPDATE merchant_account
SET balance = balance - #{amount},
    version = version + 1,
    updated_at = NOW()
WHERE merchant_id = #{merchantId}
  AND version = #{version}
  AND balance >= #{amount}
